import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Build a shared minimum-cost broadcast tree, using exact Steiner DP for
    up to twelve destinations and marginal-cost relay attachment thereafter."""
    import heapq

    topology = BroadCastTopology(src, dsts, num_partitions)
    terminals = [dst for dst in dict.fromkeys(dsts) if dst != src]
    if not terminals:
        for dst in dict.fromkeys(dsts):
            for partition in range(num_partitions):
                topology.set_dst_partition_paths(dst, partition, [])
        return topology

    def edge_cost(u, v, data):
        value = data.get("cost")
        return float(value) if value is not None else float("inf")

    priced_edges = [
        (u, v, edge_cost(u, v, data))
        for u, v, data in G.edges(data=True)
        if u != v and edge_cost(u, v, data) != float("inf")
    ]
    graph = nx.DiGraph()
    graph.add_nodes_from(G.nodes)
    graph.add_weighted_edges_from(priced_edges)
    graph.remove_edges_from(list(graph.in_edges(src)))

    for dst in terminals:
        if dst not in graph or not nx.has_path(graph, src, dst):
            raise nx.NetworkXNoPath("A destination is unreachable from source")

    if len(terminals) > 12:
        # Existing tree edges have zero marginal price: attach each new cloud
        # through whichever already-reached relay minimizes added transfer cost.
        edges = set()
        reached = {src}
        remaining = set(terminals)
        while remaining:
            def marginal_cost(u, v, data):
                return 0.0 if (u, v) in edges else data["weight"]

            lengths, paths = nx.multi_source_dijkstra(
                graph, list(reached), weight=marginal_cost
            )
            _, dst, path = min(
                (lengths[dst], dst, paths[dst])
                for dst in remaining if dst in paths
            )
            edges.update(zip(path, path[1:]))
            reached.update(path)
            remaining.discard(dst)
            remaining.difference_update(node for node in path if node in remaining)
        tree = nx.DiGraph()
        tree.add_edges_from(edges)
    else:
        nodes = list(graph.nodes)
        node_index = {node: index for index, node in enumerate(nodes)}
        incoming = [[] for _ in nodes]
        for u, v, weight in priced_edges:
            if v != src:
                incoming[node_index[v]].append((node_index[u], weight))

        mask_count = 1 << len(terminals)
        infinity = float("inf")
        dp = [[infinity] * len(nodes) for _ in range(mask_count)]
        choice = [[None] * len(nodes) for _ in range(mask_count)]

        for bit, dst in enumerate(terminals):
            dp[1 << bit][node_index[dst]] = 0.0

        for mask in range(1, mask_count):
            subset = (mask - 1) & mask
            while subset:
                other = mask ^ subset
                if subset < other:
                    for node in range(len(nodes)):
                        candidate = dp[subset][node] + dp[other][node]
                        if candidate < dp[mask][node]:
                            dp[mask][node] = candidate
                            choice[mask][node] = ("merge", subset)
                subset = (subset - 1) & mask

            queue = [(value, node) for node, value in enumerate(dp[mask])
                     if value < infinity]
            heapq.heapify(queue)
            while queue:
                distance, child = heapq.heappop(queue)
                if distance != dp[mask][child]:
                    continue
                for parent, weight in incoming[child]:
                    candidate = distance + weight
                    if candidate < dp[mask][parent]:
                        dp[mask][parent] = candidate
                        choice[mask][parent] = ("edge", child)
                        heapq.heappush(queue, (candidate, parent))

        full_mask = mask_count - 1
        source_index = node_index[src]
        if dp[full_mask][source_index] == infinity:
            raise nx.NetworkXNoPath("A destination is unreachable from source")

        edges = set()

        def collect(mask, node):
            """Recover each priced edge once from the selected Steiner states."""
            decision = choice[mask][node]
            if decision is None:
                return
            if decision[0] == "merge":
                collect(decision[1], node)
                collect(mask ^ decision[1], node)
            else:
                child = decision[1]
                edges.add((nodes[node], nodes[child]))
                collect(mask, child)

        collect(full_mask, source_index)
        tree = nx.DiGraph()
        tree.add_edges_from(edges)

    for dst in terminals:
        path = nx.dijkstra_path(tree, src, dst)
        for u, v in zip(path, path[1:]):
            for partition in range(num_partitions):
                topology.append_dst_partition_path(
                    dst, partition, [u, v, G[u][v]]
                )

    for dst in dict.fromkeys(dsts):
        if dst == src:
            for partition in range(num_partitions):
                topology.set_dst_partition_paths(dst, partition, [])

    return topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


# EVOLVE-BLOCK-END

# Helper functions that won't be evolved
def create_broadcast_topology(src: str, dsts: List[str], num_partitions: int = 4):
    """Create a broadcast topology instance"""
    return BroadCastTopology(src, dsts, num_partitions)

def run_search_algorithm(src: str, dsts: List[str], G, num_partitions: int):
    """Run the search algorithm and return the topology"""
    return search_algorithm(src, dsts, G, num_partitions)

